controls.ariaLabel:
{cartCount > 0
              ? tr(`Ouvrir mon panier, ${cartCount} article${cartCount > 1 ? 's' : ''}`, `فتح سلّتي، ${cartCount} منتج`)
              : tr('Ouvrir mon panier', 'فتح سلّتي')}

controls.onClick:
{() => onOpenFavorite({
                  sourceUrl: product.source_url,
                  title: product.title,
                  image: product.image || '',
                  priceTnd: product.pricing_tnd > 0 ? product.pricing_tnd : null,
                })}

{() => onOpenFavorite({
                  sourceUrl: store.home_url,
                  title: store.display_name || store.name,
                  image: store.logo || '',
                  priceTnd: null,
                })}
